// deploy_notices_due() rows -> one message each (D-100). Telegram text is Vietnamese (D-061);
// statuses and output from the deployer stay as they are.
const LIMIT = 4096;
const message = (row) => {
  const sha = row.sha ? String(row.sha).slice(0, 7) : '';
  if (row.kind === 'CONFIRM') {
    return {
      ask: true,
      approve: `cf:A:${row.token}`,
      reject: `cf:R:${row.token}`,
      text: [
        `🚀 Deploy ${sha}?`,
        '',
        ...(row.commits ? [row.commits, ''] : ['Không có commit mới so với worker này.', '']),
        `Theo thứ tự: ${[...(row.workers ?? []), 'n8n'].join(', ')}`,
        ...((row.offline ?? []).length ? [`Bỏ qua: ${row.offline.join(', ')} (offline)`] : []),
        'Mỗi worker chỉ cập nhật khi worker rảnh, và không nhận job mới trong lúc chờ. n8n khởi động lại nếu workflow đổi.',
        'Nút hết hạn sau 10 phút.',
      ].join('\n').slice(0, LIMIT),
    };
  }
  const targets = (row.targets ?? []).map((t) => `${t.target}: ${t.status}${t.detail ? ` (${t.detail})` : ''}`);
  const missing = row.missing ?? [];
  const texts = {
    SUCCEEDED: [`✅ Deploy xong ${sha}.`, ...targets],
    FAILED: [`❌ Deploy lỗi ${sha}; các bước sau đã hủy, không tự chạy lại hay quay về bản cũ.`, ...targets],
    CANCELLED: [`Đã hủy deploy${sha ? ` ${sha}` : ''}.`, ...(row.detail ? [row.detail] : [])],
    REFUSED: missing.length
      ? [`⛔ Không deploy ${sha}: database thiếu migration. Hãy tự chạy migration (có backup) rồi gửi lại /deploy.`, ...missing]
      : ['⛔ Không deploy được.', ...(row.detail ? [row.detail] : [])],
  };
  return { ask: false, text: (texts[row.status] ?? [`Deploy: ${row.status}`]).join('\n').slice(0, LIMIT) };
};
return $input.all().map((item) => ({ json: message(item.json) }));

// Alert when something was recovered or a video move ended (D-087), or when the set of offline workers, of
// provider-blocked videos or of videos stalled on an offline pinned worker (D-074) changes (avoids a message every minute for a lasting state).
const raw = $input.first().json.summary;
const summary = typeof raw === 'string' ? JSON.parse(raw) : raw;
const state = $getWorkflowStaticData('global');
const offline = (summary.offline_workers || []).join(',');
const offlineChanged = offline !== (state.lastOffline || '');
state.lastOffline = offline;
const blocked = (summary.blocked_videos || []).map((id) => String(id).slice(0, 8)).sort().join(',');
const blockedChanged = blocked !== (state.lastBlocked || '');
state.lastBlocked = blocked;
const stalled = (summary.stalled_pinned || [])
  .map((v) => `${String(v.video_id).slice(0, 8)} (${v.worker_id})`)
  .sort()
  .join(', ');
const stalledChanged = stalled !== (state.lastStalled || '');
state.lastStalled = stalled;
const decisions = (summary.needs_decision || []).map(
  (v) => `Video ${String(v.video_id).slice(0, 8)} v${v.version} cần bạn quyết định: bước ${v.step ?? '?'} lỗi: ${v.error ?? 'lỗi không rõ'}`,
);
const newDecisions = decisions.filter((line) => !(state.lastDecisions || []).includes(line));
state.lastDecisions = decisions;

const lines = [];
if (summary.expired_leases > 0) lines.push(`Đã thu hồi job hết hạn lease: ${summary.expired_leases}`);
if (summary.requeued > 0) lines.push(`Đã xếp lại job bị mất khỏi hàng đợi: ${summary.requeued}`);
if (summary.approvals_expired > 0) lines.push(`Yêu cầu duyệt đã hết hạn: ${summary.approvals_expired}`);
if (offlineChanged) lines.push(offline ? `Worker mất kết nối: ${offline}` : 'Tất cả worker đã hoạt động lại');
if (blockedChanged) lines.push(blocked ? `Video bị chặn do giới hạn nhà cung cấp (đang chờ, không tự đổi nhà cung cấp): ${blocked}` : 'Không còn video nào bị nhà cung cấp chặn');
if (stalledChanged) lines.push(stalled ? `Video đang chờ worker mất kết nối (file nằm trên máy đó): ${stalled}. Khi máy đó online lại, có thể chuyển video sang worker khác: /move <id> <worker>` : 'Không còn video nào chờ worker mất kết nối');
// Moves (D-087): each finished or failed move arrives once.
for (const m of summary.moves || []) {
  const id = String(m.video_id).slice(0, 8);
  lines.push(m.status === 'DONE'
    ? `Đã chuyển video ${id} từ ${m.from_worker} sang ${m.to_worker}.`
    : `Chuyển video ${id} từ ${m.from_worker} sang ${m.to_worker} thất bại${m.attempts > 0 ? ` sau ${m.attempts} lần` : ''}: ${m.error ?? 'lỗi không rõ'}. Video ở lại ${m.from_worker}.`);
}
lines.push(...newDecisions);

if (lines.length === 0) return [];
return [{ json: { text: ['⚠️ Giám sát', ...lines].join('\n') } }];
